import { test, expect } from '@playwright/test';

test.describe('Protected Page Access - Unauthenticated User', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should redirect unauthenticated user to login page when accessing protected route', async ({ page }) => {
    // Intercept the protected page request and return a 4 unauthorized response
    await page.route('/dashboard', (route) => {
      route.abort('failed');
    });

    // Navigate to the protected page
    await page.goto('/dashboard');

    // Verify the login page is displayed
    const loginPage = page.getByRole('main');
    await expect(loginPage).toBeVisible();

    // Verify the login form is visible
    const loginForm = page.getByLabel('Login');
    await expect(loginForm).toBeVisible();

    // Verify the redirect URL is correct
    const redirectLink = page.getByRole('link', { name: /login/i });
    await expect(redirectLink).toBeVisible();

    // Verify the login button is visible
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeVisible();
  });

  test('should allow authenticated user to access protected page without redirect', async ({ page }) => {
    // Set up authentication by intercepting the login API
    await page.route('/api/auth/login', (route) => {
      route.continue();
    });

    // Intercept the protected page API and return a success response
    await page.route('/api/dashboard/data', (route) => {
      route.continue();
    });

    // Navigate to the login page
    await page.goto('/login');

    // Fill in credentials using getByLabel
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Password123');

    // Click the login button using getByRole
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL('/dashboard');

    // Verify the dashboard page is displayed
    const dashboardPage = page.getByRole('main');
    await expect(dashboardPage).toBeVisible();

    // Verify the welcome message is visible
    const welcomeMessage = page.getByText(/Welcome back/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify the user profile link is visible
    const profileLink = page.getByRole('link', { name: /profile/i });
    await expect(profileLink).toBeVisible();
  });
});
